pub fn check() -> Result<(), String> {
    for (_, relative, bytes) in sources() {
        let path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../..")
            .join(relative);
        if sha(&read(&path, 3_000_000)?) != sha(bytes) {
            return Err("compiled_original_source_changed".into());
        }
    }
    Ok(())
}
pub fn build() -> Result<Value, String> {
    check()?;
    let exe = std::env::current_exe().map_err(|_| "actual_executable")?;
    let mut result = json!({"schema":"buglecat.verification.stdin-formal-holdout-jev-build.v1","runner_exe_sha256":sha(&std::fs::read(exe).map_err(|_|"actual_executable_read")?),
        "template_version":super::engine::TEMPLATE,"formal_certification":false,"production_authorized":false});
    for (role, _, bytes) in sources() {
        result[role] = json!(sha(bytes));
    }
    Ok(result)
}
